          "question": "CASO DE ESTUDO — Portal de autoatendimento para clientes\nUma empresa de serviços está implementando um portal de autoatendimento para clientes. O objetivo estratégico declarado é reduzir o volume de chamadas repetidas para a central de suporte, melhorar a experiência digital e diminuir custos operacionais. O projeto é híbrido: alguns componentes de integração com sistemas internos e controles de conformidade seguem planejamento mais preditivo, enquanto as funcionalidades do portal serão entregues em versões incrementais, com feedback de usuários-piloto.\nO patrocinador assumiu publicamente o compromisso de lançar o portal neste trimestre e deseja incluir todos os recursos inicialmente planejados: consulta de solicitações, atualização cadastral, abertura de chamados, chatbot, notificações automáticas e acompanhamento de status. O orçamento aprovado é fixo, e a reserva disponível é limitada. A equipe de suporte ao cliente afirma que o principal benefício esperado é reduzir em 20% as chamadas repetidas em até seis meses após o lançamento.\nEntretanto, ainda não há linha de base formal para o volume atual de chamadas repetidas, nenhum indicador-chave de desempenho foi aprovado, e não foi definido quem será responsável por acompanhar os benefícios após a transição para a operação. A área de Compliance informa que qualquer versão pública do portal deve obter consentimento auditável dos clientes para tratamento de dados, com evidências rastreáveis antes da entrada em produção. A equipe de produto acredita que uma versão menor, mas em conformidade, poderia gerar feedback útil e permitir validação inicial dos benefícios.\n\nO gerente do projeto precisa equilibrar o compromisso público, o orçamento fixo, as restrições de conformidade, a necessidade de medir benefícios e a entrega incremental de valor.\nQual opção melhor equilibra as restrições e maximiza o valor mensurável?",
