          "question": "CASO DE ESTUDO — Nova experiência de integração de clientes\nUm projeto híbrido está implementando uma nova experiência de integração de clientes para uma empresa de serviços financeiros. A visão aprovada afirma que o projeto deve \"reduzir o tempo de integração em 30%, mantendo as evidências de conformidade necessárias\". O patrocinador considera essa iniciativa estratégica, pois o tempo atual de integração causa abandono de clientes e retrabalho operacional.\nO projeto combina fluxos de trabalho diferentes. A validação de identidade, a retenção de evidências e os registros de auditoria seguem controles regulatórios formais. Já as telas de autoatendimento, mensagens de orientação ao cliente e recursos de produtividade operacional são refinados por meio de versões, com feedback de usuários-piloto e equipes internas.\nNas últimas semanas, surgiram interpretações conflitantes da visão. O líder de UX está priorizando autoatendimento completo, com redução máxima de etapas manuais. O líder de conformidade bloqueia designs que reduzem revisão manual sem evidência substitutiva suficiente. A equipe de operações solicita recursos de produtividade para reduzir retrabalho interno. Como resultado, decisões recentes ficaram inconsistentes: algumas favorecem velocidade, outras favorecem controle regulatório e outras favorecem eficiência interna.\nA próxima reunião de planejamento estratégico será em uma semana. O gerente do projeto precisa preparar uma recomendação que ajude as partes interessadas a tomar decisões coerentes com a visão, os critérios de sucesso e as restrições de conformidade.\n\nA equipe precisa escolher entre duas funcionalidades para a próxima versão: um assistente de autoatendimento que pode reduzir etapas para o cliente e uma melhoria interna que reduz retrabalho dos agentes. Ambas parecem contribuir para a visão, mas não há capacidade para entregar as duas agora.\nO que deve orientar a priorização?",
