          "session": 11,
          "number": 1,
          "declaredTotal": 8,
          "question": "Caso de Estudo - Aplicativo Móvel de Banco\nUm banco está desenvolvendo um aplicativo móvel voltado a clientes. O projeto é híbrido: a equipe de desenvolvimento trabalha em iterações de duas semanas, mas a entrada em operação está vinculada a um prazo regulatório fixo definido por um órgão regulador bancário, que não será alterado.\nUm Dono do Produto engajado prioriza o backlog. No meio do projeto, um diretor sênior de conformidade, que não participou da iniciação, passa a integrar o projeto e começa a levantar preocupações sobre como os dados dos clientes são tratados. Nas duas últimas iterações, a velocidade da equipe caiu de forma perceptível. Além disso, o patrocinador solicitou uma atualização de status estruturada em torno de valor de negócio, e não apenas de funcionalidades entregues.\n\nO patrocinador solicitou uma atualização de status estruturada em torno de valor de negócio. Qual é a melhor forma de reportar o progresso?",
