          "question": "Durante uma revisão executiva de um projeto híbrido, o gerente do projeto apresenta indicadores de prazo, custo e entregas concluídas. Um executivo pergunta como o progresso do projeto contribui para os benefícios previstos e para os objetivos estratégicos da organização.\nQual referência o gerente do projeto deve usar primeiro para sustentar a resposta?",
