          "session": 13,
          "number": 3,
          "declaredTotal": 8,
          "question": "Um projeto tem cronograma extremamente apertado. Em uma reunião, partes interessadas afirmam que não sabem se o projeto conseguirá atender às demandas críticas do negócio. O gerente de projeto precisa alinhar expectativa, valor e viabilidade com a equipe e as partes interessadas.\nO que ele deve fazer?",
