          "declaredTotal": 8,
          "question": "A análise trimestral de mercado mostra que concorrentes reduziram preços e o produto do projeto perdeu atratividade econômica. O patrocinador informa que o retorno sobre o investimento previsto dificilmente será alcançado se o projeto continuar sem ajustes. O gerente de projeto precisa recomendar ações para preservar valor dentro das novas condições de negócio. (Escolha duas.)\nO que ele deve fazer?",
