          "question": "Uma empresa está implementando um portal híbrido de autoatendimento para clientes. O caso de negócio aprovado apoia a estratégia de reduzir o custo do atendimento assistido e melhorar a experiência digital do cliente. A empresa se comprometeu a reduzir as transações da central de atendimento em 15% e atingir 50% de conclusão do autoatendimento em até nove meses após o lançamento.\nAntes de aprovar a próxima versão, o patrocinador pergunta como os critérios de sucesso devem ser definidos.\nQuais métricas melhor representam a entrega baseada em valor? (Escolha duas.)",
