          "question": "Um gerente de projeto está conduzindo uma iniciativa adaptativa com orçamento fixo. Após o entendimento inicial dos requisitos, a equipe visualiza de três a cinco liberações para atingir a meta do produto, mas os detalhes de cada liberação serão refinados progressivamente com feedback das partes interessadas. O que o gerente do projeto deve fazer?",
