          "number": 3,
          "declaredTotal": 8,
          "question": "Uma equipe ágil lançou um produto mínimo viável de uma nova ferramenta de software. O vice-presidente de marketing, parte interessada influente, ficou insatisfeito porque esperava mais funcionalidades no primeiro lançamento. O que o gerente de projeto deve fazer para aumentar a satisfação nos próximos lançamentos?",
