          "question": "Em um projeto ágil, o gerente de projeto teme que a equipe esteja desenvolvendo funcionalidades desalinhadas às expectativas do cliente. Para manter alinhamento contínuo e validar o progresso, com que frequência a equipe deve demonstrar o produto funcionando?",
