          "question": "Uma organização está em transição para adotar práticas ágeis. A liderança percebe que a equipe ainda tende a manter comportamentos antigos, evitando expor problemas ou pedir ajuda. O objetivo é criar um ambiente seguro, honesto e transparente para apoiar a mudança cultural. Qual ação é mais eficaz?",
