          "question": "Um gerente de projetos está desenvolvendo um projeto em uma grande organização com muitos níveis gerenciais usando uma abordagem híbrida. As fases bem definidas estão organizadas em cascata, porém o desenvolvimento apresenta muita incerteza e está sendo feito usando uma abordagem adaptativa. O gerente do projeto se reúne com um representante do escritório de projetos, que informa ter observado diversos conflitos interpessoais no projeto. O gerente responde que esses conflitos têm sido difíceis de resolver.\nQual é a principal razão provável para essa dificuldade?",
