          "number": 8,
          "declaredTotal": 9,
          "question": "Uma organização está passando por uma transformação digital e decidiu adotar práticas ágeis em seus projetos. No entanto, a cultura organizacional atual é altamente hierárquica e resistente a mudanças. O gerente de projeto identificou que a falta de transparência e a burocracia excessiva estão impedindo a adoção eficaz das práticas ágeis. Qual ação o gerente de projeto deve tomar primeiro para apoiar essa transição?",
