          "id": "book8-a2-s9-q1",
          "session": 9,
          "number": 1,
          "declaredTotal": 10,
          "question": "Caso: A central de manutenção preditiva nas fábricas\nUma empresa industrial está implantando uma central corporativa de manutenção preditiva para reduzir paradas não planejadas em suas fábricas. A solução combinará sensores instalados em equipamentos críticos, um modelo analítico para prever falhas, dashboards para gestores de manutenção e alertas operacionais para equipes locais.\nO projeto usa uma abordagem híbrida. A instalação dos sensores, a integração com sistemas industriais e a validação de dados seguem marcos preditivos, pois dependem de janelas de parada programada das fábricas. Já os dashboards, alertas e critérios de priorização das ordens de manutenção são refinados em ciclos curtos com usuários de manutenção, engenharia e operações.\nO caso de negócios foi aprovado com base em três benefícios principais: reduzir em 18% as paradas não planejadas em 12 meses, diminuir custos de manutenção corretiva e aumentar a disponibilidade dos equipamentos críticos. A diretoria também espera usar os dados consolidados para decidir futuros investimentos em modernização industrial.\nDurante a preparação do primeiro release, o gerente do projeto identifica quatro pontos relevantes:\nGovernança: Ainda não está claro quem aprova mudanças nos critérios de criticidade dos alertas, quem decide conflitos entre manutenção e produção e quais indicadores serão reportados ao comitê executivo.\nAdoção: Supervisores de produção temem que alertas frequentes reduzam a autonomia local e gerem interrupções excessivas na linha.\nRiscos: A coleta de dados dos sensores depende de uma rede industrial que apresentou instabilidade em uma fábrica piloto.\nAmbiente externo: Um novo padrão setorial de segurança operacional recomenda evidências digitais de inspeções preventivas para equipamentos de alto risco.\nO patrocinador quer manter o primeiro release para duas fábricas prioritárias, mas pede ao gerente do projeto uma recomendação para garantir que a solução seja confiável, adotada pelas áreas operacionais e capaz de sustentar benefícios mensuráveis.\n\nQual ação o gerente do projeto deve priorizar para estruturar a governança da central de manutenção preditiva?",
          "option1": "Permitir que cada fábrica defina seus próprios critérios de criticidade e reporte apenas resultados locais.",
          "optionKind": "text",
          "source": "2/9/Gabarito - 2.9.txt"
