          "question": "O Scrum Master percebe que, nas reuniões diárias, alguns membros detalham excessivamente suas tarefas, tornando a reunião longa e improdutiva. Outros relutam em compartilhar dificuldades, o que pode afetar o progresso da sprint. O que ele deve fazer para garantir que a reunião diária cumpra seu propósito?",
          "option1": "Permitir que a equipe discuta livremente todos os detalhes técnicos durante a reunião diária",
