          "question": "Uma organização está acostumada a seguir o framework Scrum, com sprints que duram 4 semanas. Um dia, um diretor da organização argumenta que 4 semanas é muito tempo e que a janela de tempo deveria ser reduzida para 2 semanas. Como o Scrum Master poderia conduzir essa mudança?",
