          "session": 1,
          "number": 10,
          "declaredTotal": 11,
          "question": "Uma organização está migrando de uma abordagem preditiva para uma abordagem ágil em um projeto de desenvolvimento de produto digital. A alta administração está frustrada porque não vê mais uma data fixa única para a entrega final, como ocorria nos cronogramas tradicionais. Ainda assim, os executivos precisam entender quando os principais recursos de negócio serão disponibilizados para apoiar decisões comerciais e comunicação com clientes.\nO que o gerente do projeto deve fazer?",
