          "question": "O gerente de projetos está liderando uma equipe de desenvolvimento ágil e percebe que o backlog do produto está desatualizado e pouco claro. O dono do produto tem dificuldades para mantê-lo priorizado, e os desenvolvedores frequentemente questionam o que deve ser trabalhado primeiro. O que o gerente de projetos deve fazer para ajudar a garantir a entrega de valor ao cliente?",
          "option1": "Aconselhar o dono do produto a atualizar o backlog sozinho para evitar atrasos no desenvolvimento.",
