          "declaredTotal": 12,
          "question": "Um gerente de projetos experiente percebe que precisa confiar na opinião de especialistas, considerar sua própria experiência e escolher a melhor forma de conduzir o trabalho conforme o contexto. Que conjunto de habilidades ele precisa desenvolver para ser bem-sucedido nesses aspectos?",
