          "number": 8,
          "declaredTotal": 12,
          "question": "Uma empresa tradicionalmente executa projetos preditivos. Um gerente de projeto foi designado para liderar um novo produto digital usando uma abordagem ágil. Durante a primeira conversa com a equipe, ele explica que está acostumado a coletar requisitos, definir o escopo e decompor todo o trabalho logo no início do projeto, tratando mudanças depois por meio de controle formal. No novo contexto, quando esse trabalho deve ocorrer?",
