          "number": 9,
          "declaredTotal": 12,
          "question": "Uma equipe ágil está usando um quadro Kanban para gerenciar seu fluxo de trabalho. Os limites de trabalho em andamento, WIP, estão indicados no cabeçalho de cada coluna. A equipe analisa o quadro durante a reunião diária para coordenar suas atividades do dia. Qual das seguintes ações a equipe pode considerar realizar? (Escolha três.)\n\nA Fazer (5) | Fazendo (4) | Teste (2) | Aceitação (3) | Produção\nHistória de usuário 13 | História de usuário 11 | História de usuário 9 | História de usuário 6 | História de usuário 1\nHistória de usuário 14 | História de usuário 12 | História de usuário 10 | História de usuário 7 | História de usuário 2\nHistória de usuário 15 | História de usuário 8 | História de usuário 3\nHistória de usuário 16 | História de usuário 4\nHistória de usuário 17 | História de usuário 5",
          "option1": "Adicionar outra história de usuário do backlog na coluna A Fazer.",
          "optionKind": "text",
