          "question": "Durante a execução de um projeto ágil, o gerente percebe que a equipe enfrenta desafios como trabalho parcialmente concluído, excesso de movimentação de tarefas entre membros e retrabalho devido a defeitos. Ele quer adotar uma abordagem que o ajude a identificar e eliminar desperdícios, tornando o fluxo mais eficiente. Qual abordagem descreve essas formas de desperdício e fornece estratégias para mitigá-las?",
