          "question": "Um projeto possui três fases principais. As fases 1 e 3 são exploratórias, com requisitos em evolução. A fase 2 possui escopo, métricas de qualidade e marcos de entrega claros e rígidos. Qual abordagem de desenvolvimento o gerente de projeto deveria escolher?",
