          "question": "Uma organização está comparando diferentes métodos adaptativos e percebe que o papel de liderança da equipe recebe títulos diferentes conforme o framework utilizado, como Scrum Master, Flow Master, coach ágil ou facilitador da equipe. Qual entendimento é mais adequado?",
