          "number": 3,
          "declaredTotal": 11,
          "question": "Uma equipe usa pontos de história para estimar histórias de usuário e problemas. No meio da sprint, o Scrum Master percebe que o progresso está abaixo do esperado. A equipe informa que algumas questões não foram estimadas com precisão porque faltavam detalhes e informações. Como o Scrum Master deve agir?",
