          "question": "O software lançado ao cliente na primeira fase do projeto apresenta muitos defeitos. O cliente exige que o desenvolvimento da nova versão, prevista para a segunda fase, seja mais transparente, com resultados vistos regularmente e sem longos intervalos de desenvolvimento. O que o gerente do projeto deve sugerir que a equipe introduza na segunda fase? (Escolha três.)",
