          "number": 8,
          "declaredTotal": 11,
          "question": "Um projeto de dois anos possui alto grau de ambiguidade e complexidade. A equipe espera mudanças conforme o escopo se torna mais claro. Para alinhar expectativas com o cliente, o gerente de projeto precisa explicar como uma abordagem iterativa será usada no ciclo de vida. O que deve ser comunicado?",
          "option1": "As tarefas serão priorizadas apenas no início do projeto, com decomposição progressiva do trabalho.",
