          "question": "A alta gerência quer um cronograma muito agressivo para um projeto inédito, com muitas incertezas e riscos elevados. Após analisar o trabalho, os recursos e o orçamento, o gerente do projeto conclui que o prazo pedido não é realista na forma tradicional. Qual abordagem ele deve recomendar para aumentar a capacidade de adaptação e entrega de resultados em um contexto tão incerto?",
