          "question": "Em um projeto ágil, um executivo que atua como responsável pelo produto pede que a equipe concentre os primeiros ciclos em definir processos, ferramentas e documentos de controle. O gerente do projeto percebe que isso pode reduzir a colaboração e atrasar a validação do produto. O que ele deve recomendar?",
