          "number": 1,
          "declaredTotal": 12,
          "question": "Durante uma iteração, a equipe percebe que uma tarefa não será concluída a tempo por causa de desafios inesperados. Outra equipe depende dessa entrega para cumprir sua parte no projeto, e o atraso pode afetar obrigações assumidas com outras áreas. Como o gerente de projeto deve tratar o problema?",
