          "question": "Um projeto ágil tem apresentado reuniões diárias longas e pouco produtivas. Alguns membros detalham tarefas técnicas em excesso, enquanto outros deixam de expor impedimentos que podem afetar a meta da sprint. O que o Scrum Master deve fazer?",
