          "session": 8,
          "number": 5,
          "declaredTotal": 12,
          "question": "Um coach ágil está apoiando uma equipe na adoção de práticas de Programação eXtreme. Após alguns treinamentos, a equipe entende a finalidade das práticas, mas continua achando a terminologia confusa e distante da linguagem usada na organização. O que o coach deve fazer?",
