          "question": "Um gerente de projeto está trabalhando com uma equipe nova no ágil e usa Scrum para conduzir o desenvolvimento. Um representante de negócios está confuso sobre a diferença entre revisão de iteração e retrospectiva. Qual explicação é mais adequada?",
