          "question": "Uma organização adotou práticas ágeis recentemente. A equipe afirma que agora há mais atividades de planejamento e não percebe benefícios claros. Alguns membros pedem ao gerente de projeto que retorne ao modelo preditivo anterior. O que o gerente de projeto deve fazer primeiro?",
