          "number": 7,
          "declaredTotal": 11,
          "question": "Um gerente de projeto estruturou seu projeto ágil de maneira menos prescritiva para causar menor perturbação para a equipe. Ele e a equipe se concentram em conduzir o trabalho por meio de um fluxo contínuo para entregar valor ao cliente em vez de usar iterações. Essa abordagem está associada a qual método ágil?",
