          "number": 9,
          "declaredTotal": 11,
          "question": "Um gerente de projeto foi designado para liderar um projeto com uma abordagem de desenvolvimento adaptativa. Durante uma reunião, as partes interessadas perguntam como o planejamento das atividades será conduzido, já que os requisitos ainda podem evoluir. Qual abordagem de planejamento deve ser seguida?",
