          "question": "Uma organização está adotando práticas ágeis para melhorar a entrega de valor. Durante a transição, parte da equipe demonstra insegurança com os novos papéis, eventos e formas de colaboração. O que o gerente de projetos deve fazer para facilitar a mudança?",
