          "question": "Uma equipe está revisando a abordagem de desenvolvimento de um novo produto e precisa associar corretamente os métodos de entrega às suas características. Combine o método de gerenciamento do projeto com o termo correto\n\nÁgil Backlog do Produto\nPreditivo Relatórios de Desempenho do Trabalho\nÁgil Gráfico Burnup",
