          "session": 12,
          "number": 8,
          "declaredTotal": 11,
          "question": "Uma organização ainda não está confortável com a adoção integral de abordagens ágeis. Para um novo projeto com incerteza moderada, o gerente de projeto recomenda iniciar com uma abordagem híbrida. O que essa recomendação significa",
