          "number": 8,
          "declaredTotal": 12,
          "question": "Uma startup está preparando o lançamento de um aplicativo inovador. Durante o planejamento inicial, a equipe percebe que ainda há incerteza relevante sobre como os usuários usarão o produto e quais funcionalidades realmente gerarão valor. O prazo de lançamento é importante, mas a equipe quer reduzir o risco de construir uma solução pouco útil.\nO que o gerente de projeto deve apoiar?",
