          "session": 16,
          "number": 1,
          "declaredTotal": 13,
          "question": "Caso: O piloto que precisava provar valor\nUma organização de serviços está preparando a primeira entrega de um portal de autoatendimento para clientes. O objetivo do produto é reduzir chamadas ao centro de atendimento, melhorar a experiência do cliente e permitir que solicitações simples sejam resolvidas diretamente pelo portal. O projeto é conduzido de forma híbrida: há governança executiva para acompanhar benefícios e riscos operacionais, enquanto a equipe de produto trabalha com incrementos frequentes e feedback de usuários.\nO patrocinador solicitou evidências de que a primeira entrega está gerando benefícios mensuráveis, não apenas funcionalidades concluídas. A meta inicial definida no caso de negócios é reduzir em 12% as chamadas relacionadas a solicitações simples de atendimento. A área de operações, porém, teme um lançamento amplo, pois sua capacidade de suporte inicial permite acompanhar apenas 10% da base de usuários sem comprometer o atendimento normal.\nNa revisão de prontidão do release, a equipe apresenta as seguintes informações: o recurso de remarcação de consultas está pronto e aprovado nos testes funcionais; o fluxo de disputas de cobrança foi adiado para uma entrega futura; os dados de chamadas podem ser segmentados por região; e há um controle de alternância de recursos, que permite ativar ou desativar funcionalidades para grupos específicos de usuários. A área de atendimento informa que pode acompanhar indicadores de volume de chamadas, satisfação dos usuários, incidentes operacionais e solicitações escaladas durante o piloto.\nO líder de produto quer lançar o recurso pronto rapidamente para demonstrar progresso. O patrocinador quer dados de benefícios antes de autorizar uma ampliação maior. A área de operações solicita cautela para não criar um volume de suporte acima da capacidade. O gerente do projeto precisa recomendar uma estratégia de lançamento que entregue valor, produza evidências mensuráveis e respeite a capacidade operacional.\n\nQual é a principal vantagem de usar o controle de alternância de recursos neste cenário?",
          "option1": "Eliminar a necessidade de envolver a área de operações, já que o recurso pode ser desligado a qualquer momento.",
          "optionKind": "text",
