          "number": 4,
          "declaredTotal": 7,
          "question": "Uma equipe ágil está mantendo um fluxo contínuo de trabalho, mas pequenas decisões técnicas e operacionais estão sendo encaminhadas ao gerente do projeto para aprovação. Isso está criando filas, atrasando a resolução de impedimentos simples e reduzindo a autonomia da equipe. O que o gerente do projeto deve fazer?",
