          "question": "Uma empresa que sempre usou abordagem preditiva decidiu iniciar uma transição gradual para métodos ágeis. Alguns gerentes de projeto acreditam que perderão relevância porque as equipes ágeis terão dono do produto, Scrum Master e membros autogerenciáveis. Como essa preocupação deve ser tratada?",
