          "question": "Uma organização pretende iniciar um projeto para desenvolver um novo produto, mas a alta administração está preocupada com a possibilidade de o projeto não contribuir para os objetivos estratégicos de longo prazo. Qual ação o gerente de projeto deve realizar primeiro?",
