          "session": 9,
          "number": 2,
          "declaredTotal": 4,
          "question": "Um gerente de projeto foi designado para liderar a construção de uma nova usina termoelétrica. Ao revisar o termo de abertura, ele quer confirmar onde estão documentados padrões governamentais obrigatórios, limites regulatórios e outras condições que restringem a execução do projeto. Que parte do documento ele deve analisar primeiro?",
