          "session": 10,
          "number": 1,
          "declaredTotal": 3,
          "question": "CASO DE ESTUDO — Expansão logística em ambiente externo instável\nUm projeto híbrido de expansão logística está sendo planejado para ampliar a capacidade de distribuição de uma empresa varejista em uma região metropolitana. O projeto inclui contratação de transportadoras, adequação de um centro de cross-docking, implantação de novos roteiros de entrega, integração com sistemas de rastreamento e treinamento das equipes operacionais.\nO patrocinador espera reduzir atrasos de entrega, aumentar a previsibilidade das rotas e melhorar a experiência dos clientes. No entanto, o ambiente externo está instável. Nas últimas semanas, surgiram notícias sobre uma nova restrição municipal para circulação de caminhões em horários de pico, possível reajuste tarifário de um fornecedor crítico e uma exigência ambiental ainda em discussão para veículos de entrega urbana.\nA equipe recebe essas informações de forma informal, por notícias, contatos com fornecedores e conversas com associações locais. Porém, ainda não há critério claro sobre o que deve ser monitorado, quem deve acompanhar cada sinal externo, quando escalar o tema e como essas informações devem afetar o planejamento. A operação quer começar rapidamente a implantação das novas rotas, enquanto compras deseja concluir negociações com fornecedores antes de qualquer ajuste.\nO gerente do projeto precisa estruturar a iniciação e o planejamento integrado, mantendo atenção ao ambiente externo e preparando a execução sem reagir de forma desordenada a cada notícia informal.\n\nDurante a iniciação, o patrocinador descreve o objetivo como \"melhorar a logística da região\". A operação interpreta isso como reduzir atrasos, a área comercial espera melhorar a experiência do cliente, e compras entende que a prioridade é reduzir custo de frete.\nO que o gerente do projeto deve fazer para fortalecer a autorização inicial?",
