          "declaredTotal": 3,
          "question": "CASO DE ESTUDO — Modernização energética de edifícios\nUma organização nacional aprovou uma iniciativa para modernizar 40 edifícios administrativos com controles inteligentes de energia. O objetivo estratégico é reduzir o consumo energético, melhorar a sustentabilidade operacional e demonstrar compromisso público com metas ambientais. O patrocinador deseja apresentar o plano integrado de gerenciamento do projeto aos executivos na próxima semana.\nO projeto combina componentes com características diferentes. A substituição de painéis elétricos, sensores de segurança e integrações com sistemas prediais existentes precisa atender a normas técnicas, requisitos de segurança e regras de conformidade. Essas atividades exigem aprovações formais, inspeções e janelas de intervenção previamente autorizadas pelos responsáveis pelos edifícios.\nAo mesmo tempo, há recursos experimentais de economia de energia, como algoritmos de ajuste automático de iluminação, controle de climatização baseado em ocupação e painéis digitais de recomendação para gestores prediais. A equipe ainda não sabe quais desses recursos produzirão maior economia em cada tipo de edifício. Alguns prédios têm sistemas antigos, outros já possuem automação parcial, e os dados históricos de consumo variam em qualidade.\nA equipe ainda não separou claramente as restrições fixas de segurança e conformidade dos elementos experimentais. Também não foram definidos os indicadores que comprovarão os benefícios de sustentabilidade, como redução de consumo, economia financeira, emissões evitadas, conforto dos usuários ou estabilidade operacional. O patrocinador pede ao gerente de projeto que escolha ainda hoje entre uma abordagem preditiva ou adaptativa. Os executivos querem uma decisão rápida, mas o PMO alerta que o plano integrado precisa justificar a abordagem escolhida, as métricas de valor, os critérios de controle e as evidências esperadas de sustentabilidade.\n\nNo caso dado, antes da aprovação executiva do plano integrado, os executivos perguntam como saberão se o projeto está entregando valor. Qual ação o gerente do projeto deve priorizar?",
          "option1": "Definir indicadores de benefícios e evidências de sustentabilidade antes de consolidar o plano.",
